export function validateHeartRateInput(i: HeartRateInput, lang: "en" | "es" = "en"): string | null {
  if (!i.age || i.age <= 0 || i.age > 120) {
    return lang === "es" ? "Ingresa una edad válida." : "Enter a valid age.";
  }
  return null;
}

